<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import {useRoute} from 'vue-router';import {AgGridVue} from 'ag-grid-vue3';import {api,dateTime,money,messageOf} from '@/lib/api';import StatusBadge from '@/components/StatusBadge.vue';const route=useRoute(),id=String(route.params.id),batch=ref<any>(),tab=ref('documents'),documents=ref<any[]>([]),findings=ref<any[]>([]),selected=ref<any>(),loading=ref(true);const docCols=[{field:'number',headerName:'NF',width:100},{field:'issued_at',headerName:'Emissão',valueFormatter:(p:any)=>dateTime(p.value),width:160},{field:'direction',headerName:'Direção',width:110},{field:'issuer_tax_id',headerName:'Emitente',width:150},{field:'recipient_tax_id',headerName:'Destinatário',width:150},{field:'total_value',headerName:'Valor NF',valueFormatter:(p:any)=>money(p.value),width:150},{field:'ibs_cbs_base',headerName:'Base IBS/CBS',valueFormatter:(p:any)=>money(p.value),width:150},{field:'ibs_value',headerName:'IBS',valueFormatter:(p:any)=>money(p.value),width:120},{field:'cbs_value',headerName:'CBS',valueFormatter:(p:any)=>money(p.value),width:120},{field:'items_count',headerName:'Itens',width:90},{field:'status',headerName:'Status',width:120}];const findingCols=[{field:'severity',headerName:'Severidade',width:120},{field:'category',headerName:'Categoria',width:160},{field:'rule_code',headerName:'Regra',width:190},{field:'title',headerName:'Achado',flex:1,minWidth:260},{field:'fiscal_document.number',headerName:'NF',width:100},{field:'status',headerName:'Status',width:120}];onMounted(load);async function load(){batch.value=(await api.get(`/analyses/${id}`)).data;await Promise.all([loadDocuments(),loadFindings()]);loading.value=false;if(['queued','processing'].includes(batch.value.status))setTimeout(load,5000)}async function loadDocuments(){documents.value=(await api.get(`/analyses/${id}/documents`,{params:{per_page:500}})).data.data}async function loadFindings(){findings.value=(await api.get(`/analyses/${id}/findings`,{params:{per_page:500}})).data.data}async function openDoc(e:any){selected.value=(await api.get(`/analyses/${id}/documents/${e.data.id}`)).data}async function download(r:any){const res=await api.get(`/reports/${r.id}/download`,{responseType:'blob'});const url=URL.createObjectURL(res.data);const a=document.createElement('a');a.href=url;a.download=`auditoria-${id}.${r.type==='pdf'?'pdf':'xlsx'}`;a.click();URL.revokeObjectURL(url)}async function resolve(f:any){const notes=prompt('Informe a justificativa da resolução:');if(notes===null)return;await api.patch(`/analyses/${id}/findings/${f.id}`,{status:'resolved',resolution_notes:notes});await loadFindings()}const totals=computed(()=>batch.value?.summary||{});</script>
<template><div v-if="loading" class="card">Carregando auditoria...</div><template v-else><section class="card hero"><div><div class="eyebrow">{{batch.company.legal_name}} · {{batch.catalog_version.version}}</div><h2>{{batch.name}}</h2><p>{{batch.period_start||'Período não informado'}} a {{batch.period_end||'—'}} · Criada em {{dateTime(batch.created_at)}}</p></div><div class="actions"><StatusBadge :value="batch.status"/><button v-for="r in batch.reports" @click="download(r)">Baixar {{r.type.toUpperCase()}}</button></div></section><section class="kpis"><article><span>Documentos</span><strong>{{batch.document_count}}</strong></article><article><span>Valor total</span><strong>{{money(totals.total_value)}}</strong></article><article><span>Base IBS/CBS</span><strong>{{money(totals.ibs_cbs_base)}}</strong></article><article><span>IBS + CBS</span><strong>{{money(Number(totals.ibs_value||0)+Number(totals.cbs_value||0))}}</strong></article></section><div class="tabs"><button :class="{active:tab==='documents'}" @click="tab='documents'">Documentos</button><button :class="{active:tab==='findings'}" @click="tab='findings'">Críticas ({{findings.length}})</button><button :class="{active:tab==='method'}" @click="tab='method'">Método e snapshot</button></div><section class="card" v-show="tab==='documents'"><AgGridVue theme="legacy" class="ag-theme-quartz grid" :rowData="documents" :columnDefs="docCols" :pagination="true" :paginationPageSize="50" @rowClicked="openDoc"/></section><section class="card" v-show="tab==='findings'"><AgGridVue theme="legacy" class="ag-theme-quartz grid" :rowData="findings" :columnDefs="findingCols" :pagination="true" :paginationPageSize="50" @rowDoubleClicked="resolve($event.data)"/><p class="hint">Clique duas vezes em uma crítica para registrar a resolução.</p></section><section class="card prose" v-show="tab==='method'"><h3>Rastreabilidade</h3><dl><dt>Versão de catálogo</dt><dd>{{batch.catalog_version.version}}</dd><dt>Hash da fonte</dt><dd><code>{{batch.catalog_version.source_sha256}}</code></dd><dt>Regra de cálculo</dt><dd>UB16-10, calculada item a item com Decimal e arredondamento configurado.</dd><dt>Snapshot</dt><dd>Os resultados não mudam quando uma versão posterior do catálogo é publicada.</dd></dl></section><div class="drawer" v-if="selected"><button class="drawer-close" @click="selected=null">×</button><h2>NF {{selected.number}}</h2><p><code>{{selected.access_key}}</code></p><div class="kpis compact"><article><span>Valor</span><strong>{{money(selected.total_value)}}</strong></article><article><span>Base</span><strong>{{money(selected.ibs_cbs_base)}}</strong></article></div><h3>Itens</h3><table><thead><tr><th>#</th><th>Descrição</th><th>NCM/EX</th><th>Encontrado</th><th>Esperado</th><th>Situação</th></tr></thead><tbody><tr v-for="i in selected.items"><td>{{i.item_number}}</td><td>{{i.description}}</td><td>{{i.ncm}} / {{i.ex_code||'—'}}</td><td>{{i.actual_cst}} / {{i.actual_cclass_trib}}</td><td>{{i.expected_cst}} / {{i.expected_cclass_trib}}</td><td><StatusBadge :value="i.classification_status"/></td></tr></tbody></table><details><summary>XML normalizado</summary><pre>{{JSON.stringify(selected.normalized,null,2)}}</pre></details></div></template>

</template>
